@import "tailwindcss";
@import "./styles/studio-pro-design-system.css";
@import "./styles/design-tokens.css";

/* Apply design system variables to base layer for Tailwind v4 */
@layer base {
  :root {
    /* Design system colors */
    --bg-void: #040810;
    --bg-primary: #080f1a;
    --bg-secondary: #0d1526;
    --bg-elevated: #111d2e;
    --bg-hover: #162236;
    --border-subtle: #1a2744;
    --border-default: #243452;
    --border-active: #2d4470;
    --text-primary: #e8edf5;
    --text-secondary: #8896b0;
    --text-dimmed: #4a5568;
    --text-mono: #5b8dd9;
    --accent-purple: #7c6af7;
    --accent-amber: #e8a020;
    --accent-green: #2ecc7a;
    --accent-red: #e05050;
    --accent-cyan: #38b2c8;
  }

  body {
    background-color: #040810;
    color: #e8edf5;
    font-family: 'Inter', system-ui, sans-serif;
  }

  /* Utility classes */
  .mono {
    font-family: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;
    color: #5b8dd9;
  }

  /* Card/Panel components */
  .studio-card,
  .studio-panel {
    background: #0d1526;
    border: 1px solid #1a2744;
    border-radius: 8px;
    padding: 20px;
  }

  /* Primary buttons */
  .btn-studio-primary {
    background: #7c6af7;
    color: #040810;
    border: none;
    border-radius: 5px;
    font-weight: 600;
    padding: 10px 20px;
    cursor: pointer;
    transition: opacity 150ms ease;
  }

  .btn-studio-primary:hover {
    opacity: 0.9;
  }

  /* Secondary buttons */
  .btn-studio-secondary {
    background: transparent;
    border: 1px solid #334155;
    color: #8896b0;
    border-radius: 5px;
    font-weight: 600;
    padding: 10px 20px;
    cursor: pointer;
    transition: all 150ms ease;
  }

  .btn-studio-secondary:hover {
    border-color: #475569;
    color: #e8edf5;
  }

  /* Navigation */
  .studio-nav {
    background: #080f1a;
    border-bottom: 1px solid #1a2744;
  }

  .studio-nav-tab {
    color: #4a5568;
    background: transparent;
    border: none;
    padding: 12px 20px;
    cursor: pointer;
    transition: color 150ms ease;
    border-bottom: 2px solid transparent;
  }

  .studio-nav-tab:hover {
    color: #8896b0;
  }

  .studio-nav-tab-active {
    color: #e8edf5;
    border-bottom-color: #7c6af7;
  }

  /* Advisory panel (replaces red blocked banner) */
  .studio-advisory {
    border-left: 3px solid #e8a020;
    background: #0d1526;
    border-top: 1px solid #1a2744;
    border-right: 1px solid #1a2744;
    border-bottom: 1px solid #1a2744;
    border-radius: 8px;
    padding: 20px;
  }
}

/* Legacy variables - will be gradually migrated to design system */
:root {
  --font-display: 'Inter', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;
  --brand-cyan-100: #d5f6f3;
  --brand-cyan-300: #7ad6d1;
  --brand-amber-200: #efcc93;
  --brand-amber-400: #d6a95c;
  --brand-rose-300: #d08383;
  --cinematic-gradient-panel: linear-gradient(180deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02));
  --cinematic-gradient-chip: linear-gradient(140deg, rgba(214, 169, 92, 0.18), rgba(122, 214, 209, 0.1));
  --studio-glow-soft: 0 0 22px rgba(122, 214, 209, 0.16);
  --studio-glow-strong: 0 0 28px rgba(214, 169, 92, 0.22);
  --studio-shadow-cinematic: 0 24px 60px rgba(0, 0, 0, 0.45);
  --studio-shadow-elevated: 0 16px 34px rgba(0, 0, 0, 0.34);
  --studio-panel-space: 12px;
  --studio-panel-space-sm: 8px;
  --studio-panel-space-lg: 16px;
  --studio-blur-sm: blur(8px);
  --studio-blur-md: blur(12px);
  --studio-blur-lg: blur(16px);
  --studio-border-glow: rgba(255, 255, 255, 0.16);
  --studio-border-glow-strong: rgba(122, 214, 209, 0.44);
  --state-idle-a: rgba(122, 214, 209, 0.08);
  --state-generating-a: rgba(125, 211, 252, 0.14);
  --state-reviewing-a: rgba(214, 169, 92, 0.12);
  --state-failed-a: rgba(96, 120, 170, 0.14);
  --state-completed-a: rgba(214, 169, 92, 0.2);
  --bg-deep: #050505;
  --bg-panel: rgba(16, 16, 18, 0.62);
  --bg-card: rgba(21, 21, 24, 0.72);
  --bg-card-hover: rgba(30, 30, 34, 0.82);
  --border: rgba(255, 255, 255, 0.1);
  --border-accent: rgba(214, 169, 92, 0.35);
  --text-primary: #f2eee9;
  --text-secondary: #b8b1a7;
  --text-muted: #8d867b;
  --accent-cyan: #7ad6d1;
  --accent-purple: #9f8dc5;
  --accent-green: #78b38a;
  --accent-orange: #b88762;
  --accent-amber: #d6a95c;
  --accent-red-soft: #d08383;
  --panel-shadow: 0 20px 44px rgba(0, 0, 0, 0.42);
  --studio-space-xs: 6px;
  --studio-space-sm: 10px;
  --studio-space-md: 14px;
  --studio-space-lg: 20px;
  --studio-space-xl: 28px;
}

* {
  box-sizing: border-box;
}

html, body, #root {
  height: 100%;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg-void);
  color: var(--text-primary);
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 13px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
  letter-spacing: 0.01em;
  position: relative;
  margin: 0;
  padding: 0;
}

#root {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  width: 100%;
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: var(--bg-primary);
}
::-webkit-scrollbar-thumb {
  background: var(--border-default);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--text-dimmed);
}

input, textarea, select {
  font-family: inherit;
}

.glass-panel {
  background: var(--bg-panel);
  backdrop-filter: blur(18px);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: var(--panel-shadow);
}

.glass-card {
  background: var(--bg-card);
  backdrop-filter: blur(12px);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.28);
}

.cinematic-panel {
  border-radius: 1rem;
  border: 1px solid var(--studio-border-glow);
  background: var(--cinematic-gradient-panel);
  backdrop-filter: var(--studio-blur-md);
  box-shadow: var(--studio-shadow-elevated), var(--studio-glow-soft);
  padding: var(--studio-panel-space);
}

.studio-status-chip {
  border-radius: 999px;
  border: 1px solid var(--studio-border-glow);
  background: var(--cinematic-gradient-chip);
  padding: 2px 8px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.studio-icon-chip {
  border-radius: 10px;
  border: 1px solid var(--studio-border-glow);
  background: rgba(0, 0, 0, 0.28);
  backdrop-filter: var(--studio-blur-sm);
  box-shadow: var(--studio-glow-soft);
}

.studio-nav-link {
  border-radius: 8px;
  transition: all 180ms ease;
}

.studio-nav-link:hover {
  box-shadow: var(--studio-glow-soft);
}

.accent-glow {
  box-shadow: 0 0 20px rgba(0, 200, 255, 0.15);
}

.neon-border {
  border-color: var(--accent-cyan);
  box-shadow: 0 0 8px rgba(0, 200, 255, 0.3), inset 0 0 8px rgba(0, 200, 255, 0.05);
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.status-active {
  background: var(--accent-green);
  box-shadow: 0 0 6px var(--accent-green);
}

.status-warning {
  background: var(--accent-amber);
  box-shadow: 0 0 6px var(--accent-amber);
}

.status-error {
  background: #ef4444;
  box-shadow: 0 0 6px #ef4444;
}

.progress-bar {
  height: 3px;
  border-radius: 2px;
  background: rgba(255,255,255,0.1);
}

.progress-fill {
  height: 100%;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--accent-cyan), var(--accent-purple));
}

.btn-primary {
  background: linear-gradient(135deg, rgba(214, 169, 92, 0.28), rgba(214, 169, 92, 0.14));
  color: var(--text-primary);
  border: 1px solid rgba(214, 169, 92, 0.5);
  border-radius: 10px;
  padding: 8px 16px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: transform 0.2s ease, opacity 0.2s ease, box-shadow 0.2s ease;
}

.btn-primary:hover {
  opacity: 0.95;
  transform: translateY(-1px);
  box-shadow: 0 0 24px rgba(214, 169, 92, 0.24);
}

.btn-ghost {
  background: rgba(255, 255, 255, 0.03);
  color: var(--text-secondary);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 10px;
  padding: 7px 14px;
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn-ghost:hover {
  border-color: rgba(214, 169, 92, 0.48);
  background: rgba(214, 169, 92, 0.08);
  color: var(--text-primary);
}

h1, h2, h3, h4 {
  letter-spacing: 0.08em;
  font-family: var(--font-display);
  line-height: 1.2;
}

p {
  line-height: 1.55;
}

.studio-surface {
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: linear-gradient(180deg, rgba(20, 20, 22, 0.7), rgba(10, 10, 12, 0.68));
  box-shadow: 0 14px 32px rgba(0, 0, 0, 0.34);
}

.studio-surface-muted {
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(8, 8, 10, 0.42);
}

.studio-empty-state {
  border-radius: 12px;
  border: 1px dashed rgba(255, 255, 255, 0.24);
  background: linear-gradient(180deg, rgba(16, 16, 18, 0.64), rgba(9, 9, 10, 0.5));
  padding: var(--studio-space-lg);
}

.studio-skeleton {
  position: relative;
  overflow: hidden;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
}

.studio-skeleton::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.16), transparent);
  animation: studio-shimmer 1.4s ease-in-out infinite;
}

.studio-fade-in {
  animation: studio-fade-in 260ms ease-out both;
}

@keyframes studio-shimmer {
  100% { transform: translateX(100%); }
}

@keyframes studio-fade-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

.waveform-line {
  stroke: var(--accent-cyan);
  fill: none;
  stroke-width: 1.5;
  opacity: 0.7;
}

@keyframes pulse-glow {
  0%, 100% { opacity: 0.6; }
  50% { opacity: 1; }
}

@keyframes spin-slow {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.render-activity-panel {
  position: fixed;
  right: 16px;
  bottom: 18px;
  width: min(360px, calc(100vw - 24px));
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: linear-gradient(145deg, rgba(7, 10, 16, 0.94), rgba(10, 14, 24, 0.86));
  padding: 12px;
  overflow: hidden;
  backdrop-filter: blur(10px);
  z-index: 50;
  transition: box-shadow 280ms ease, border-color 280ms ease, transform 260ms ease;
}

.render-status-active {
  box-shadow: 0 0 0 1px rgba(122, 214, 209, 0.18), 0 0 32px rgba(122, 214, 209, 0.28);
  animation: render-pulse-glow 2s ease-in-out infinite;
}

.render-status-completed {
  box-shadow: 0 0 0 1px rgba(120, 179, 138, 0.2), 0 0 24px rgba(120, 179, 138, 0.16);
}

.render-status-failed {
  box-shadow: 0 0 0 1px rgba(208, 131, 131, 0.24), 0 0 26px rgba(208, 131, 131, 0.22);
}

.render-activity-shimmer {
  position: absolute;
  top: 0;
  left: -45%;
  width: 45%;
  height: 100%;
  background: linear-gradient(110deg, transparent, rgba(255, 255, 255, 0.16), transparent);
  animation: render-shimmer 1.8s linear infinite;
  pointer-events: none;
}

.director-console-panel {
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  border: 1px solid rgba(122, 214, 209, 0.24);
  background: linear-gradient(165deg, rgba(8, 10, 15, 0.95), rgba(9, 14, 24, 0.92));
  box-shadow: 0 0 0 1px rgba(122, 214, 209, 0.08), 0 12px 34px rgba(0, 0, 0, 0.55);
  padding: 12px;
}

.director-console-monitor {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(transparent 49%, rgba(255, 255, 255, 0.03) 50%, transparent 51%),
    radial-gradient(500px 220px at 10% 0%, rgba(122, 214, 209, 0.08), transparent 70%);
  background-size: 100% 3px, 100% 100%;
  mix-blend-mode: screen;
}

.director-console-control {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.director-console-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: #8d867b;
}

.director-console-input {
  width: 100%;
  border-radius: 10px;
  border: 1px solid rgba(122, 214, 209, 0.3);
  background: rgba(4, 8, 14, 0.75);
  color: #f2eee9;
  padding: 8px 10px;
  font-size: 12px;
  outline: none;
  transition: box-shadow 180ms ease, border-color 180ms ease;
}

.director-console-input:focus {
  border-color: rgba(122, 214, 209, 0.55);
  box-shadow: 0 0 0 1px rgba(122, 214, 209, 0.25), 0 0 20px rgba(122, 214, 209, 0.18);
}

.director-console-generate {
  width: 100%;
  border-radius: 12px;
  border: 1px solid rgba(214, 169, 92, 0.52);
  background: linear-gradient(135deg, rgba(214, 169, 92, 0.35), rgba(214, 169, 92, 0.15));
  color: #f2eee9;
  padding: 10px 12px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  cursor: pointer;
  transition: transform 180ms ease, box-shadow 180ms ease, opacity 180ms ease;
}

.director-console-generate:hover {
  transform: translateY(-1px);
  box-shadow: 0 0 22px rgba(214, 169, 92, 0.28);
}

.director-console-generate:disabled {
  opacity: 0.6;
  cursor: wait;
}

.co-director-collab-panel {
  border: 1px solid rgba(56, 189, 248, 0.32);
  background: radial-gradient(circle at 10% 0%, rgba(56, 189, 248, 0.14), rgba(10, 12, 20, 0.92) 65%);
  border-radius: 14px;
  padding: 0.85rem;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04), 0 0 30px rgba(56, 189, 248, 0.12);
}

.co-director-collab-head {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.55rem;
}

.co-director-collab-title,
.co-director-collab-mode {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(186, 230, 253, 0.95);
}

.co-director-collab-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
}

.co-director-collab-card {
  border: 1px solid rgba(255, 255, 255, 0.11);
  background: rgba(8, 12, 20, 0.7);
  border-radius: 10px;
  padding: 0.6rem;
  min-height: 76px;
}

.co-director-collab-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: rgba(161, 161, 170, 0.95);
  margin-bottom: 0.3rem;
}

.co-director-collab-card p {
  margin: 0;
  font-size: 12px;
  line-height: 1.45;
  color: rgba(228, 228, 231, 0.94);
}

.co-director-collab-footer {
  margin-top: 0.6rem;
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(161, 161, 170, 0.95);
}

.collab-presence {
  position: fixed;
  right: 14px;
  top: 82px;
  width: min(300px, calc(100vw - 26px));
  border-radius: 12px;
  border: 1px solid rgba(96, 165, 250, 0.35);
  background: linear-gradient(170deg, rgba(7, 10, 16, 0.95), rgba(12, 18, 31, 0.92));
  padding: 8px;
  z-index: 47;
  box-shadow: 0 0 26px rgba(56, 189, 248, 0.14);
  pointer-events: none;
}

.collab-presence-title {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: rgba(191, 219, 254, 0.95);
  margin-bottom: 6px;
}

.collab-presence-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.collab-presence-row {
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  padding: 5px 7px;
  background: rgba(2, 6, 12, 0.5);
}

.collab-presence-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: #34d399;
  box-shadow: 0 0 8px rgba(52, 211, 153, 0.65);
  margin-right: 6px;
}

.collab-presence-name {
  font-size: 11px;
  color: rgba(226, 232, 240, 0.96);
}

.collab-presence-meta {
  display: block;
  margin-top: 2px;
  font-size: 10px;
  color: rgba(148, 163, 184, 0.94);
}

.collab-panel {
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: linear-gradient(160deg, rgba(6, 10, 18, 0.92), rgba(10, 15, 27, 0.9));
  padding: 10px;
}

.collab-panel-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.collab-panel-title {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(226, 232, 240, 0.96);
}

.collab-panel-sub,
.collab-foot {
  margin-top: 5px;
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(148, 163, 184, 0.92);
}

.collab-vote-row {
  margin-top: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.collab-vote-btn,
.collab-mini-btn {
  border-radius: 8px;
  border: 1px solid rgba(125, 211, 252, 0.35);
  background: rgba(14, 116, 144, 0.16);
  color: rgba(224, 242, 254, 0.95);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 6px 8px;
}

.collab-comment-box {
  margin-top: 8px;
  display: flex;
  gap: 6px;
}

.collab-input {
  flex: 1;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.32);
  background: rgba(2, 6, 12, 0.55);
  color: rgba(226, 232, 240, 0.96);
  font-size: 12px;
  padding: 7px 9px;
}

.collab-feed {
  margin-top: 9px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.collab-feed-row {
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.11);
  background: rgba(2, 6, 12, 0.45);
  padding: 6px 8px;
}

.collab-feed-author {
  display: block;
  font-size: 10px;
  color: rgba(165, 243, 252, 0.94);
  margin-bottom: 2px;
}

.collab-feed-text {
  font-size: 12px;
  color: rgba(226, 232, 240, 0.96);
}

.studio-brain-panel {
  border-radius: 16px;
  border: 1px solid rgba(56, 189, 248, 0.28);
  background: linear-gradient(165deg, rgba(7, 12, 20, 0.92), rgba(6, 10, 15, 0.9));
  padding: 12px;
  box-shadow: 0 0 30px rgba(56, 189, 248, 0.11);
}

.studio-brain-head {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.studio-brain-title,
.studio-brain-audit {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: rgba(186, 230, 253, 0.95);
}

.studio-brain-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.studio-brain-card {
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.11);
  background: rgba(2, 6, 12, 0.45);
  padding: 8px;
}

.studio-brain-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.11em;
  color: rgba(125, 211, 252, 0.95);
  margin-bottom: 6px;
}

.studio-brain-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

